import React, { useEffect, useState } from "react";
import axios from "axios";

function ExamPage({ exam, onExit }) {
  const [questions, setQuestions] = useState(null);
  const token = localStorage.getItem("token");

  useEffect(() => {
    // Placeholder: try to fetch questions if a future endpoint exists.
    // Falls es keinen Endpoint gibt, zeigen wir einen Hinweis und ggf. laden aus JSON später.
    const fetchQuestions = async () => {
      try {
        const res = await axios.get(`http://127.0.0.1:8000/api/students/exams/${exam.id}/questions/`, {
          headers: { Authorization: `Token ${token}` }
        });
        setQuestions(res.data);
      } catch (_e) {
        setQuestions([]);
      }
    };
    fetchQuestions();
  }, [exam?.id, token]);

  return (
    <div style={{ padding: 20 }}>
      <h2>📝 {exam.title}</h2>
      <p style={{ color: "#6b7280" }}>{exam.description}</p>

      {questions === null && <p>Lade Fragen …</p>}

      {Array.isArray(questions) && questions.length === 0 && (
        <div style={{ background: "#fff8e1", border: "1px solid #fde68a", padding: 12, borderRadius: 8 }}>
          Für diese Prüfung ist noch kein Fragen-Endpunkt implementiert.
          Wir zeigen hier die Oberfläche; die Anbindung kann später ergänzt werden.
        </div>
      )}

      {Array.isArray(questions) && questions.length > 0 && (
        <ol>
          {questions.map((q, idx) => (
            <li key={idx} style={{ marginBottom: 12 }}>
              <div style={{ fontWeight: 600 }}>{q.text || q.question || `Frage ${idx + 1}`}</div>
              {Array.isArray(q.options) && (
                <ul>
                  {q.options.map((opt, i) => (
                    <li key={i}>{opt}</li>
                  ))}
                </ul>
              )}
            </li>
          ))}
        </ol>
      )}

      <button onClick={onExit} style={{ marginTop: 16 }}>Zurück zu den Prüfungen</button>
    </div>
  );
}

export default ExamPage;
